#!/usr/bin/env python3
"""Embed the compiled Strata shaders into spv_data.hpp (committed).

Run after regenerating a .spv:

    glslangValidator -V strata_q2_0_gemv.comp -o strata_q2_0_gemv.spv
    python3 embed.py

Both the .spv (the data) and spv_data.hpp (the embed) are committed, so the
build never needs glslangValidator and the binary needs no shader files at run
time.
"""
import pathlib

# Only the Strata-specific shaders (not the Q-Infer-native ones).
SHADERS = ["strata_q2_0_gemv", "strata_swiglu_quant"]


def main() -> None:
    d = pathlib.Path(__file__).resolve().parent
    out = [
        "// Generated by shaders/embed.py from the .spv files - do not edit.",
        "#pragma once",
        "",
        "#include <cstdint>",
        "",
        "namespace strata::kernels::igpu::shaders {",
        "",
    ]
    for name in SHADERS:
        data = (d / f"{name}.spv").read_bytes()
        sym = "k" + "".join(p.capitalize() for p in name.replace(".", "_").split("_")) + "Spv"
        out.append(f"inline constexpr std::uint8_t {sym}[] = {{")
        for i in range(0, len(data), 16):
            chunk = ", ".join(f"0x{b:02x}" for b in data[i : i + 16])
            out.append(f"    {chunk},")
        out.append("};")
        out.append(f"inline constexpr std::size_t {sym}Size = sizeof({sym});")
        out.append("")
    out.append("}  // namespace strata::kernels::igpu::shaders")
    (d / "spv_data.hpp").write_text("\n".join(out) + "\n")
    print(f"wrote {d / 'spv_data.hpp'}")


if __name__ == "__main__":
    main()
